run('CMS sanitizer URL bypasses',function(){
 $html=(new CmsContentSanitizer)->clean('<a href=javascript:alert(1)>Unquoted</a><a href="java&#x73;cript:alert(1)">Encoded</a>');$doc=new DOMDocument;@$doc->loadHTML($html);$unsafe=false;foreach($doc->getElementsByTagName('a') as $anchor)if(str_starts_with(strtolower($anchor->getAttribute('href')),'javascript:'))$unsafe=true;check('CMS sanitizer rejects executable encoded/unquoted links',!$unsafe);
});
$pages=['Store Settings'=>fn()=>(new App\Http\Controllers\Admin\EcommerceSettingController)->edit(),'CMS Pages'=>fn()=>(new App\Http\Controllers\Admin\AdminPageController)->index(req()),'CMS create'=>fn()=>(new App\Http\Controllers\Admin\AdminPageController)->create(),'CMS edit'=>fn()=>(new App\Http\Controllers\Admin\AdminPageController)->edit(Page::first()),'Menu Builder'=>fn()=>(new App\Http\Controllers\Admin\AdminNavigationMenuController)->index(),'Global Analytics'=>fn()=>(new App\Http\Controllers\Admin\AdminAnalyticsController)->index(req()),'Admin Team'=>fn()=>(new App\Http\Controllers\Admin\AdminUserController)->index(req()),'Admin edit'=>fn()=>(new App\Http\Controllers\Admin\AdminUserController)->edit(Admin::find(99)),'Roles'=>fn()=>(new App\Http\Controllers\Admin\AdminRoleController)->index(),'Notifications'=>fn()=>(new App\Http\Controllers\Admin\AdminNotificationController)->index(req()),'Audit logs'=>fn()=>(new App\Http\Controllers\Admin\AdminAuditLogController)->index(req()),'Backups'=>fn()=>(new App\Http\Controllers\Admin\AdminBackupController)->index(),'Email Templates'=>fn()=>(new App\Http\Controllers\Admin\AdminEmailTemplateController)->index(),'Email edit'=>fn()=>(new App\Http\Controllers\Admin\AdminEmailTemplateController)->edit(EmailTemplate::first())];$render=[];
foreach($pages as $label=>$factory){try{$html=$factory()->render();$render[$label]=['result'=>'PASS','bytes'=>strlen($html)];check('Page render: '.$label,strlen($html)>500);}catch(Throwable $e){$render[$label]=['result'=>'ERROR','detail'=>$e->getMessage()];check('Page render: '.$label,false,get_class($e).' '.$e->getMessage());}}
foreach(['admin.settings.update','admin.pages.store','admin.navigation-menus.items.store','admin.analytics.index','admin.admin-users.store','admin.admin-roles.store','admin.notifications.send','admin.audit-logs.export','admin.backups.download','admin.email-templates.update'] as $name)run('Permission '.$name,function()use($app,$name){$mock=Mockery::mock(Admin::class)->makePartial();$mock->shouldReceive('isActive')->andReturn(true);$mock->shouldReceive('hasAdminPermission')->andReturn(false);Auth::guard('admin')->setUser($mock);$r=req();$r->setRouteResolver(fn()=>$app['router']->getRoutes()->getByName($name));try{(new App\Http\Middleware\AdminMiddleware)->handle($r,fn()=>response('allowed'));check('Unauthorized admin denied: '.$name,false);}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){check('Unauthorized admin denied: '.$name,$e->getStatusCode()===403);}});AuthFix();
file_put_contents(__DIR__.'/../checks.json',json_encode($results,JSON_PRETTY_PRINT));file_put_contents(__DIR__.'/../page-render-checks.json',json_encode($render,JSON_PRETTY_PRINT));echo 'COMPLETED '.count($results).' checks: '.count(array_filter($results,fn($r)=>$r['result']==='PASS')).' PASS, '.count(array_filter($results,fn($r)=>$r['result']==='ISSUE')).' ISSUE, '.count(array_filter($results,fn($r)=>$r['result']==='ERROR'))." ERROR. SQLite memory and fixture files only.\n";
